from django.db import migrations, models

STAGE_FIELD = dict(
    choices=[('uncycled', 'Uncycled'), ('cycled', 'Cycled'), ('mature', 'Mature')],
    help_text="Uncycled while the nitrogen cycle gets going, cycled once ammonia and nitrite stay at zero, "
              "mature once it's been stable for months",
    max_length=10,
)


def keep_todays_icons(apps, schema_editor):
    """Tanks already set up count as cycled, which shows the young version they show now. A chosen old version,
    and a retired tank that was showing its old version, keep the old one."""
    Tank = apps.get_model('aquarium', 'Tank')
    AppSettings = apps.get_model('aquarium', 'AppSettings')
    settings = AppSettings.objects.filter(pk=1).first()
    aging = not (settings and settings.disable_icon_aging)
    for tank in Tank.objects.all():
        changed = []
        if tank.icon_choice.endswith('-old'):
            tank.icon_choice = tank.icon_choice[:-len('-old')] + '-young'
            tank.icon_version = 'old'
            changed += ['icon_choice', 'icon_version']
        elif tank.is_archived and aging and tank.icon_choice != 'custom':
            tank.icon_version = 'old'
            changed.append('icon_version')
        if changed:
            tank.save(update_fields=changed)


